= MtChimney_EventScript_Maxie
lockall
playbgm MUS_ENCOUNTER_MAGMA FALSE
msgbox	The power contained in the METEORITE…By amplifying its power with this machine, MT. CHIMNEY's volcanic activity will instantly intensify…Its energy will grow deep inside the crater and… Fufufu…
applymovement LOCALID_MT_CHIMNEY_MAXIE Common_Movement_FacePlayer
waitmovement 0
playse SE_PIN
applymovement LOCALID_MT_CHIMNEY_MAXIE Common_Movement_ExclamationMark
waitmovement 0
applymovement LOCALID_MT_CHIMNEY_MAXIE Common_Movement_Delay48
waitmovement 0
msgbox	MAXIE: Hm? Who are you?… … … … … … … … … … … …I'd heard ARCHIE bemoaning a child who's been meddling in TEAM AQUA's affairs.It must be you he meant.Humph! So you're thinking of interfering with us, TEAM MAGMA?Now you listen. Long ago, living things used the land to live and grow.That is why land is all important! It is the cradle of all!That is why TEAM MAGMA is dedicated to the expansion of the land mass.It is for further advancement of humankind and POKéMON!And for that, we need the power of what sleeps within this mountain…Oh! There was no need for you to learn that much.But, no matter! I'll teach you the consequences of meddling in our grand design!
trainerbattle_no_intro TRAINER_MAXIE_MT_CHIMNEY MtChimney_Text_MaxieDefeat
msgbox	MAXIE: But, enough. I will back off this time.But don't think that this is the last you've seen of TEAM MAGMA.Fufufu…Even without the METEORITE, if we obtain that ORB… Fufufu…
closemessage
delay 30
fadescreen FADE_TO_BLACK
removeobject LOCALID_MT_CHIMNEY_MAXIE
removeobject LOCALID_MT_CHIMNEY_MAGMA_GRUNT_1
removeobject LOCALID_MT_CHIMNEY_TABITHA
removeobject LOCALID_MT_CHIMNEY_MAGMA_GRUNT_2
setflag FLAG_HIDE_MT_CHIMNEY_TEAM_MAGMA
fadescreen FADE_FROM_BLACK
setobjectxyperm LOCALID_MT_CHIMNEY_ARCHIE 10 12
addobject LOCALID_MT_CHIMNEY_ARCHIE
call_if_eq VAR_FACING DIR_EAST MtChimney_EventScript_ArchieApproachPlayerEast
call_if_eq VAR_FACING DIR_NORTH MtChimney_EventScript_ArchieApproachPlayerNorth
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
msgbox	ARCHIE: PLAYER! Thank you!With your help, we thwarted TEAM MAGMA's destructive plan!But… You… Whose side are you on?Ah, it doesn't matter.We will remain vigilant and keep up our pursuit of TEAM MAGMA.PLAYER, we shall meet again!
closemessage
call_if_eq VAR_FACING DIR_EAST MtChimney_EventScript_ArchieExitEast
call_if_eq VAR_FACING DIR_NORTH MtChimney_EventScript_ArchieExitNorth
removeobject LOCALID_MT_CHIMNEY_ARCHIE
setflag FLAG_HIDE_MT_CHIMNEY_TEAM_AQUA
setflag FLAG_DEFEATED_EVIL_TEAM_MT_CHIMNEY
clearflag FLAG_HIDE_FALLARBOR_HOUSE_PROF_COZMO
setflag FLAG_HIDE_METEOR_FALLS_1F_1R_COZMO
clearflag FLAG_HIDE_MT_CHIMNEY_LAVA_COOKIE_LADY
releaseall
end
= MtChimney_EventScript_ArchieExitNorth
applymovement LOCALID_MT_CHIMNEY_ARCHIE MtChimney_Movement_ArchieExitNorth
waitmovement 0
return
= MtChimney_EventScript_ArchieExitEast
applymovement LOCALID_MT_CHIMNEY_ARCHIE MtChimney_Movement_ArchieExitEast
waitmovement 0
return
= MtChimney_EventScript_ArchieApproachPlayerNorth
